  "source": "def investigate(context, acquire):
    events = acquire("events")
    seen = set()
    total = 0
    for event in events:
        event_id = event["event_id"]
        if event_id not in seen:
            seen.add(event_id)
            total += event["work"]
    return {"findings": [], "unresolved": [], "ratio": total}",
  "scope": "Deduplicates events by event_id and sums work once per unique ID.",
  "lesson": "Duplicate deliveries must not double-count work; distinct IDs with equal work both count."
}
